\begin{align*} \mathbf{R}^2 &= \begin{pmatrix} 4/5 & 3/5 \\ 3/5 & -4/5 \end{pmatrix} \begin{pmatrix} 4/5 & 3/5 \\ 3/5 & -4/5 \end{pmatrix} \\ &= \begin{pmatrix} (4/5)(4/5) + (3/5)(3/5) & (4/5)(3/5) + (3/5)(-4/5) \\ (3/5)(4/5) + (-4/5)(3/5) & (3/5)(3/5) + (-4/5)(-4/5) \end{pmatrix} \\ &= \begin{pmatrix} 16/25 + 9/25 & 12/25 - 12/25 \\ 12/25 - 12/25 & 9/25 + 16/25 \end{pmatrix} \\ &= \begin{pmatrix} 25/25 & 0 \\ 0 & 25/25 \end{pmatrix} \\ &= \begin{pmatrix} 1 & 0 \\ 0 & 1 \end{pmatrix} = \mathbf{I}. \end{align*}

